export type TopicKnowledge = {
  summary: string;
  theory: { heading: string; body: string }[];
  objectives: string[];
  examples: string[];
  mistakes: string[];
  references: { title: string; url: string; source: string }[];
};

type Ref = TopicKnowledge["references"][number];
const SHURE: Ref = { title: "Audio Systems Guide for Video and Film Production", url: "https://content-files.shure.com/Pubs/audio-systems-guide-for-video-and-film-production/audio-systems-guide-for-video-and-film-production-english.pdf", source: "Shure" };
const SHURE_MIC: Ref = { title: "Microphone directionality and polar-pattern basics", url: "https://www.shure.com/en-eu/insights/microphone-directionality-polar-pattern-basics/", source: "Shure" };
const DPA: Ref = { title: "Microphone University", url: "https://www.dpamicrophones.com/mic-university/", source: "DPA Microphones" };
const BMD_EDIT: Ref = { title: "DaVinci Resolve official editing training", url: "https://www.blackmagicdesign.com/products/davinciresolve/training", source: "Blackmagic Design" };
const ADOBE_CONT: Ref = { title: "Continuity editing in film", url: "https://www.adobe.com/creativecloud/video/hub/ideas/what-is-continuity-editing-in-film.html", source: "Adobe" };
const ADOBE_SPLIT: Ref = { title: "J-cuts and L-cuts", url: "https://www.adobe.com/uk/creativecloud/video/discover/j-cut-and-l-cut.html", source: "Adobe" };
const BMD_COLOR: Ref = { title: "The Colorist Guide to DaVinci Resolve 20", url: "https://documents.blackmagicdesign.com/UserManuals/DaVinci-Resolve-20-Colorist-Guide.pdf", source: "Blackmagic Design" };
const ACES: Ref = { title: "ACES documentation", url: "https://docs.acescentral.com/", source: "Academy Color Encoding System" };
const YALE: Ref = { title: "Film Analysis Guide", url: "https://filmanalysis.yale.edu/", source: "Yale University" };
const BFI: Ref = { title: "BFI filmmaking resources", url: "https://www.bfi.org.uk/education-research/education", source: "British Film Institute" };
const BAFTA: Ref = { title: "BAFTA Guru film craft archive", url: "https://www.bafta.org/guru", source: "BAFTA" };
const CSATF: Ref = { title: "Industry Safety Bulletins", url: "https://www.csatf.org/production-affairs-safety/safety-bulletins/", source: "Contract Services" };
const DGA: Ref = { title: "The Director's Team", url: "https://www.dga.org/The-Guild/Departments/Directors-Team", source: "Directors Guild of America" };

function lesson(summary: string, theory: [string,string][], objectives: string[], examples: string[], mistakes: string[], references: Ref[]): TopicKnowledge {
  return { summary, theory: theory.map(([heading,body]) => ({ heading, body })), objectives, examples, mistakes, references };
}

export const storyPostKnowledge: Record<string, TopicKnowledge> = {
  "Sound Perspective & Story Function": lesson(
    "Sound perspective is the audible point of view of a scene: distance, directness, reverberation, frequency balance and level tell us where a listener seems to be and what deserves attention.",
    [["The listening camera","A close microphone produces a high direct-to-reverberant ratio and intimate detail; a distant position admits reflections and environmental sound. Picture size and sonic distance may agree for realism or disagree deliberately for memory, dread or subjectivity."],["Figure and ground","Dialogue, effects, ambience and music compete for a limited perceptual foreground. Automation, spectral space and selective silence can move one element forward without simply making every track louder."],["Point of audition","A scene may sound objectively from the room, spatially from the camera, or subjectively from a character. Muffled highs after an explosion or narrowed ambience during panic is meaningful only when the transition establishes the changed point of audition."],["Continuity across cuts","Consistent room tone and acoustic character help separate microphone takes feel like one place. Perspective should change plausibly when cutting from a wide shot to a close-up; a sudden dry voice over a reverberant wide can expose the production process."],["Design from intention","Write what the audience should notice before choosing sounds. Build a neutral reality layer first, then alter one dimension—distance, width, density or frequency—to express story rather than decorating the scene indiscriminately."]],
    ["Identify objective, camera-linked and subjective sound perspective.","Design a perspective change that redirects attention without harming intelligibility."],
    ["A whispered close voice over a wide landscape makes internal thought dominate physical distance.","Room tone narrows before a revelation, then the full environment returns after the character reacts."],
    ["Matching every sound's level while ignoring distance and reverberation.","Adding music before the scene's informational hierarchy works without it."],[SHURE,DPA]),

  "Microphone Types & Polar Patterns": lesson(
    "Microphone choice combines transducer behavior with directionality: the type affects sensitivity and handling, while the polar pattern describes response by angle and frequency—not a hard capture boundary.",
    [["Transducers","Dynamic microphones generate voltage through coil motion and tolerate high levels; condensers use a charged capsule and active electronics, commonly offering greater sensitivity and requiring power. Neither category is automatically more cinematic."],["Reading a polar plot","Zero degrees is on-axis. Cardioid rejects most strongly behind; super- and hypercardioid narrow the front but develop rear lobes; figure-eight accepts front and rear while rejecting the sides; omni has no aiming null."],["Patterns change with frequency","Published diagrams often show several frequencies because off-axis response is not uniform. Reflected high frequencies can become colored even when broadband rejection looks impressive."],["Placement follows rejection","Aim the useful axis toward the actor and the null toward the dominant unwanted source. A supercardioid boom pointed correctly may reject a wall or generator better than a nominally tighter microphone pointed carelessly."],["Choose for the whole scene","Consider working distance, room reflections, wind, handling, wardrobe, powering and backup placement. The best specification is irrelevant if the microphone cannot remain in a clean, consistent position."]],
    ["Interpret cardioid, supercardioid, figure-eight and omni polar diagrams.","Select a microphone by source, room and placement constraints rather than brand prestige."],
    ["A hypercardioid boom uses its side null toward HVAC while keeping the rear lobe away from a reflective ceiling.","An omni lavalier stays tonally consistent as an actor turns their head."],
    ["Treating the polar pattern as a wall outside which no sound exists.","Placing a rear-lobed pattern with its rear aimed at the loudest reflection."],[SHURE_MIC,DPA]),

  "Placement, Proximity & Phase": lesson(
    "Microphone position usually changes recorded dialogue more than changing microphone models: distance determines direct sound, angle changes timbre and multiple arrival times create phase interaction.",
    [["Distance is signal-to-noise","Halving source distance greatly raises the wanted voice relative to a roughly constant room and electronics floor. Boom as close as framing and performance permit rather than compensating later with gain."],["Axis and mouth geometry","Aim near the mouth or upper chest according to the desired tone and plosive risk. Moving off-axis can soften consonants, but every microphone colors off-axis sound differently."],["Proximity effect","Pressure-gradient directional microphones build low-frequency response at very close distances. It can add weight or create inconsistent boominess as an actor moves; omni microphones do not exhibit the same effect."],["Time arrival and comb filtering","When two microphones capture one source at different delays, summed frequencies alternately reinforce and cancel. Monitor the actual combination, respect substantial spacing, and choose one primary microphone when the blend becomes hollow."],["Movement discipline","A boom operator follows the speaking actor and anticipates head turns while preserving angle and distance. Rehearsal reveals shadows, frame edges, reflective zones and handoff moments before the take."]],
    ["Place a boom for high direct-to-ambient ratio without entering frame.","Recognize proximity coloration and comb filtering by ear."],
    ["A boom shifts between actors during their listening beats so it arrives before each line.","A lav is delayed or one source is chosen instead of summing it blindly with the boom."],
    ["Keeping the boom safely far away and raising preamp gain.","Mixing boom and lav equally without checking polarity and arrival time."],[SHURE,DPA]),

  "Gain Staging, Noise & Headroom": lesson(
    "Gain staging preserves useful dialogue above acoustic and electronic noise while leaving enough peak margin for performance surprises; it is a chain decision, not a target meter number in isolation.",
    [["Start at the source","Reduce generators, wardrobe rub, HVAC and microphone distance before touching gain. A preamp cannot separate a quiet voice from room noise already captured at the capsule."],["Preamp before fader","Input gain determines how strongly the microphone signal reaches the recorder's converter. A downstream fader changes monitoring or mix level but cannot undo clipped input or improve an underfed preamp."],["Headroom","Dialogue has fast peaks that average meters conceal. Rehearse the loudest delivery, leave margin, and use limiters only as a safety net; a limiter is not permission to ride the converter near clipping."],["Noise sources","Self-noise, preamp noise, radio noise and the acoustic noise floor have different remedies. Solo and trace the chain: substitute cable, channel, transmitter or microphone instead of applying broad denoising by reflex."],["Record format and meters","Use an appropriate bit depth and understand whether meters show peak, true peak or average behavior. 32-bit float may protect certain recorder-stage overloads, but it cannot repair an overloaded microphone, wireless transmitter or analog input."]],
    ["Set dialogue gain from a rehearsed peak with defensible headroom.","Locate noise at the acoustic, microphone, wireless, preamp or recording stage."],
    ["The actor performs the loudest line during check and the mixer leaves transient margin.","A noisy channel is isolated by swapping one component at a time."],
    ["Recording extremely low because normalization is available later.","Assuming 32-bit float makes every point in the chain impossible to clip."],[SHURE,DPA]),

  "Production Dialogue Workflow": lesson(
    "Production dialogue workflow protects performance and editability through preparation, microphone strategy, monitoring, metadata, reports and explicit communication before and after each take.",
    [["Preflight","Read the scene for movement, overlap, wardrobe, props and noise. Frequency-coordinate wireless channels, inspect batteries and media, jam timecode where used, and capture a spoken test before company is waiting."],["Primary and safety coverage","Choose the boom as a coherent primary perspective when possible, then use lavaliers or plant microphones to cover width, occlusion or unpredictable staging. Backups should solve identified risks, not produce uncontrolled phase-heavy mixtures."],["Monitor the record return","Closed headphones reveal rubbing, RF hits, distortion and off-axis dialogue that speakers on set hide. Watch performers and boom position while listening; meters cannot tell whether a word was intelligible."],["Slate and metadata","Record scene, take, track names and notes consistently. Mark false starts, wild lines, noise and microphone problems so editorial knows what exists and which track should lead."],["After the take","State a concise problem immediately when another take can fix it. Capture room tone and wild lines before the location changes, then verify files and handoff reports with the media."]],
    ["Plan a boom/lav strategy from blocking and wardrobe.","Deliver labeled production sound with usable notes and backups."],
    ["A wide master uses plants where the boom cannot enter, while close coverage returns to the boom.","The mixer flags a clean wild line after a prop masked one word."],
    ["Discovering wardrobe noise only in post because no one monitored the take.","Recording many microphones without labeling or identifying the preferred track."],[SHURE,DPA]),

  "Ambience, Room Tone & Wild Tracks": lesson(
    "Ambience establishes a place over time; room tone is the stable acoustic bed needed beneath dialogue edits; wild tracks capture specific sounds or lines without synchronized picture.",
    [["Three different assets","Ambience may contain characteristic events such as traffic or birds. Room tone aims for the location's steady background under the same conditions. A wild track isolates an action, prop or line for editorial flexibility."],["Match the production state","Record tone with the same microphones, gains, positions, doors, appliances and crew stillness as the scene. A silent room after equipment has moved will not match the noise spectrum between dialogue clips."],["Duration and variation","Capture long enough to contain a clean section and natural evolution. Looping a few seconds can reveal periodic repetition; gather alternate perspectives when the scene uses wide and close sonic viewpoints."],["Editorial function","Room tone fills gaps created by removing words and smoothing split edits. Character ambience can bridge locations or signal time, but prominent events must not repeat impossibly across cuts."],["Log what cannot be seen","Name each file and note microphone perspective. Record isolated props at several intensities and distances so sound editorial can match the action rather than stretching one unsuitable take."]],
    ["Distinguish room tone, ambience, wild effects and wild dialogue.","Record editable environmental assets that match production perspective."],
    ["Thirty seconds of set tone is captured before anyone changes the practical fan.","A door is recorded close, medium and from the dialogue microphone position."],
    ["Calling any quiet recording room tone even after the acoustic state changed.","Recording only one short ambience full of irreversible foreground events."],[SHURE,DPA]),

  "Monitoring, Sync & Troubleshooting": lesson(
    "Reliable location sound depends on hearing the recorded signal, maintaining a shared time reference, and tracing failures in order rather than guessing under pressure.",
    [["Monitoring path","Listen after the recorder input whenever possible. Check both isolated channels and the production mix; a headphone feed from the camera or wireless receiver may conceal a fault later in the chain."],["Timecode and slate","Timecode identifies corresponding moments but does not guarantee drift-free sample clocks. Jam devices, verify frame rate and time-of-day, recheck after power changes, and retain a visible and audible slate as a robust fallback."],["Latency and phase","Digital wireless, camera returns and processing add delay. Do not judge performance timing from a delayed return, and inspect alignment before combining independently delayed microphones."],["A fault tree","For silence, follow source, capsule, cable, transmitter, receiver, input routing, arming, media and monitoring. Change one item at a time; random rebooting destroys evidence and can create a second problem."],["Escalation","Know when the remedy is a fast cable swap and when production must pause for safety or data integrity. Announce what is affected, what remains recorded and what test proves recovery."]],
    ["Verify sync settings and slate backup before recording.","Troubleshoot a silent, noisy or drifting channel systematically."],
    ["A re-jam is followed by a slate test and playback confirmation.","A missing lav is traced from transmitter RF to receiver routing to armed track."],
    ["Assuming matching timecode displays guarantee zero drift.","Listening only to a convenience mix instead of the isolated recorded tracks."],[SHURE,DPA]),

  "Location Sound Chapter Boss": lesson(
    "The location-sound capstone integrates script analysis, microphone choice, gain, monitoring, sync, environmental control and post handoff into dialogue that remains believable through an edited scene.",
    [["Design the coverage","Annotate each beat for actor movement, frame width, overlapping speech and sound hazards. Assign a primary microphone and a credible backup for every setup."],["Test the difficult moment","Rehearse the widest frame, loudest line, head turn, costume movement and radio range. A successful easy line does not validate the scene's failure point."],["Record with evidence","Monitor returns, preserve headroom, name tracks, mark takes and record tone, wild dialogue and props before striking. Keep a sound report that an editor can understand without calling the set."],["Build the edit test","Assemble a short dialogue sequence from the production files. Listen for perspective jumps, phase, missing syllables, background discontinuity and sync drift at every cut."],["Evaluate the system","Separate performance limitations from recording faults. Defend where boom, lav or plant led, document one prevented failure and identify the earliest workflow change that would improve a weak result."]],
    ["Execute a complete sound plan for a blocked dialogue scene.","Prove editability through a synchronized scene and documented handoff."],
    ["The master uses a plant, close-ups use boom, and lavs protect overlapping movement.","The final report points editorial to the clean alternate for a masked word."],
    ["Treating isolated clean clips as success without cutting the scene.","Finishing the shoot without matched tone, wild assets or track notes."],[SHURE,DPA]),

  "Dramatic Question, Conflict & Change": lesson("A scene becomes dramatic when a live question can change: someone wants an outcome, resistance makes the outcome uncertain, and the encounter leaves at least one condition different.",[["The live question","Phrase the question so this scene can answer or transform it: will she confess, escape, persuade or refuse? A broad theme is not yet a playable dramatic question."],["Conflict as resistance","Conflict may come from another person, environment, duty or incompatible desires. Volume is not conflict; resistance is whatever makes the objective costly or uncertain."],["Value change","Track a value such as trust, freedom, status or knowledge from the opening state to the closing state. If nothing changes, the scene may be exposition without dramatic movement."],["Escalation","Each tactic should alter pressure or reveal information. Repetition at the same intensity stalls; escalation changes the available choices."],["Directing the turn","Stage and emphasize the beat where the balance changes. Camera, performance and sound should clarify the consequence without redundantly announcing it."]],["State a scene's dramatic question and value change.","Identify resistance and escalating tactics beat by beat."],["A polite job interview turns when the applicant realizes the employer knows the lie.","A locked door converts a private intention into an urgent physical problem."],["Calling disagreement conflict when neither character risks anything.","Ending in the same dramatic state despite many lines."],[BAFTA,BFI]),
  "Character Objective & Action": lesson("An objective is the result a character pursues from another person or the situation; an action is the playable verb used to pursue it moment by moment.",[["Objective","Use an immediate result—make him stay—not an internal state such as be sad. The actor can pursue a result and discover emotion as consequence."],["Obstacle","A useful obstacle actively opposes the objective and can change. It gives the performer something to work against rather than a biography to illustrate."],["Playable verbs","To reassure, corner, seduce, shame and distract produce different behavior. Avoid result notes such as be angrier that ask the actor to display an emotion."],["Tactics and adjustment","When one action fails, the character changes tactic. The director can adjust the verb while protecting the actor's ownership of how it appears."],["Subtext","Spoken text and pursued action need not match. A character saying congratulations while trying to diminish someone creates behavior the camera can observe."]],["Translate interpretation into an objective, obstacle and playable actions.","Give a concise adjustment without prescribing facial results."],["Try to recruit him replaces play the scene more urgently.","A comforting line is played as an attempt to control the listener."],["Giving psychological lectures immediately before a take.","Using emotion words as if they were physical actions."],[BAFTA,BFI]),
  "Beat Analysis & Scene Shape": lesson("A beat is a unit of dramatic action that changes when new information, behavior or resistance causes a new tactic; beat analysis exposes the scene's internal shape.",[["Finding boundaries","Mark a new beat when the pursued action, power relation or shared knowledge changes—not at every pause or paragraph."],["Naming beats","Label beats with active verbs and consequences: she tests him; he evades; she reveals proof. Labels should make progression visible."],["Shape","Map tension, knowledge and power across beats. A scene can rise, release and reverse rather than climb at one constant pitch."],["Performance use","Actors need not perform a diagram, but the map helps the director locate unclear transitions and choose where to rehearse."],["Audiovisual emphasis","Coverage and sound can reveal or conceal a turn. A held reaction may make the consequence stronger than cutting to the speaker who caused it."]],["Divide a scene at genuine changes in dramatic action.","Design emphasis around the decisive turn."],["A joke is its own beat only when it changes trust or tactic.","The camera stays on the listener as withheld information lands."],["Equating every line with a beat.","Forcing every beat to increase loudness and speed."],[BAFTA,BFI]),
  "Directing Actors with Playable Notes": lesson("Playable direction gives an actor a specific action, circumstance or task they can attempt while leaving room for truthful discovery.",[["Observe before fixing","Describe the precise story problem—her decision arrives before we see the evidence—rather than judging the performance as flat."],["Give one adjustment","Change an objective, action, image, relationship or physical task. One testable note lets actor and director learn what caused the difference."],["Protect process","Ask what language helps this performer; some work externally, others from circumstance or imagery. Consent and trust are practical conditions for good work."],["Rehearsal modes","Table work clarifies text, blocking rehearsal reveals physical problems, and camera rehearsal calibrates scale. Do not exhaust the emotional event before recording without a reason."],["Evaluate on playback carefully","Playback can answer framing or continuity questions, but compulsive self-monitoring may narrow spontaneity. Agree when it is useful."]],["Turn a vague result note into a playable adjustment.","Diagnose performance in relation to the scene rather than personal taste."],["Protect the secret becomes test whether he already knows.","Handle the cup while avoiding eye contact creates a playable obstacle."],["Line-reading the desired delivery as the first solution.","Giving multiple contradictory notes between takes."],[BAFTA,DGA]),
  "Blocking, Staging & Visual Point of View": lesson("Blocking arranges bodies, gaze and movement in space; staging makes relationships legible; point of view determines whose access to that arrangement guides the audience.",[["Motivated movement","Movement should arise from objective, environment or a change in relationship. Arbitrary marks feel mechanical because action and intention separate."],["Power geometry","Distance, height, orientation and who controls an exit can externalize status. A shift in the relationship can motivate a new spatial composition."],["Reveal and conceal","Doorways, foregrounds and eyelines regulate information. Ask what the chosen observer can know at each moment."],["Camera dependency","A block that reads in the room may collapse through a lens. Check overlaps, screen direction, focus distance and background from the actual camera position."],["Iterate together","Find actor movement first, then refine camera and light without making performers serve equipment unnecessarily. Rehearse changes at working speed."]],["Block a scene from objectives and changing relationships.","Choose a camera viewpoint that controls audience knowledge."],["One character crosses behind the desk only after gaining authority.","A doorway withholds a witness until the instant the protagonist notices them."],["Placing actors solely to make a symmetrical frame.","Changing marks for lighting without explaining the dramatic reason."],[BAFTA,BFI]),
  "Coverage, Inserts & Editorial Intent": lesson("Coverage is a designed set of angles and moments that lets editorial preserve performance, space and story emphasis; it is not indiscriminate insurance.",[["Editorial question","Decide whose experience leads each beat and what information must be visible. That determines masters, singles, shared frames and reaction coverage."],["Master function","A master establishes spatial and performance continuity, but it need not be visually neutral. It can carry the scene if its changing composition expresses the drama."],["Singles and eyelines","Lens position, size and eyeline distance affect intimacy and spatial matching. Record clean entrances, exits and listening behavior, not only dialogue delivery."],["Inserts","An insert earns time when it supplies necessary knowledge, tactile emphasis or a cut point. Record hands and props with matching light, direction and action phase."],["Shoot for transitions","Give editorial pre-roll, post-roll, overlaps and room for sound bridges. Check the intended sequence before striking to find missing causal links."]],["Build a minimal coverage plan from beats and editorial point of view.","Capture inserts and reactions with usable continuity handles."],["A two-shot carries reconciliation; singles appear only when trust breaks.","The key insert shows which key was selected, not merely an attractive close-up."],["Shooting every scene as master, overs and close-ups by habit.","Ending takes immediately after the last line."],[BAFTA,BFI]),
  "Tone, Rhythm & Ethical Collaboration": lesson("Tone is the audience's governing relationship to the material; rhythm is how pressure and release unfold; ethical collaboration keeps creative risk specific, consensual and safe.",[["Tone is relational","The same event can invite dread, tenderness or absurdity through performance scale, framing, timing and sound. Define the intended audience relation rather than an adjective alone."],["Rhythmic variety","Pace comes from changes in thought, action and silence, not uniformly fast delivery. Preserve room for discoveries and consequences."],["Shared language","Explain purpose, boundaries and practical expectations before vulnerable work. Invite questions through a clear chain of communication."],["Consent is ongoing","Agreement to a script is not unlimited consent to improvisation or physical contact. Choreograph sensitive action and honor changed boundaries without retaliation."],["Leadership under pressure","Time pressure magnifies ambiguity. The director protects focus by prioritizing, communicating one decision and never trading physical or psychological safety for a take."]],["Coordinate performance, image and sound toward a stated tone.","Run a boundary-aware rehearsal with clear communication."],["A comic scene is played sincerely while framing and timing create the audience's distance.","Intimate action is closed-set, choreographed and repeated consistently."],["Telling departments to make it darker without defining the dramatic effect.","Using surprise to provoke an unconsented authentic reaction."],[BAFTA,DGA]),
  "Directed Scene Chapter Boss": lesson("The directing capstone turns text into a coherent scene through dramatic analysis, actor process, motivated blocking, intentional coverage and an edit that proves the choices survived production.",[["Prep the dramatic engine","Write question, objectives, obstacles, beats, value change and intended tone. Identify the turn the audience must understand."],["Rehearse behavior","Explore playable actions and motivated movement before locking marks. Resolve safety and consent needs explicitly."],["Design point of view","Choose a visual and sonic strategy for audience knowledge, then create only the coverage needed to protect crucial alternatives."],["Direct the set","Communicate priorities, watch performance rather than equipment, make one useful adjustment per take and record continuity notes."],["Prove it in editorial","Cut the scene and evaluate whether objective, turn and consequence read without explanation. Use the edit's failures to diagnose directing or coverage omissions."]],["Direct and edit a complete dramatic scene.","Defend choices using observable audience information and performance change."],["Coverage narrows as a character loses options, then breaks axis at the reversal.","A repeated viewer confusion reveals that the decisive reaction was never captured."],["Judging the shoot by attractive dailies rather than a working scene.","Changing tone, blocking and performance simultaneously without comparison."],[BAFTA,BFI]),

  "The Cut and Viewer Attention": lesson("A cut redirects the viewer from one field of information to another; its timing and the placement of the incoming point of interest determine whether the transition feels discovered, anticipated or late.",[["Attention before continuity","Know where the eye is at the end of the outgoing shot and what it must acquire next. Similar screen position eases the search; deliberate displacement creates effort or surprise."],["Performance timing","Thoughts, glances, breaths and reactions often supply stronger cut points than words. A frame earlier can anticipate a decision; a frame later can let its consequence settle."],["Information threshold","Leave after essential information is read and arrive before the next necessary event. Cutting only because a line ends makes rhythm grammatical rather than dramatic."],["Motion and sound","Movement can carry attention through a cut, while an audio lead can prepare a new space. Both reduce the cognitive reset caused by picture replacement."],["Test in motion","Compare trims at playback speed, not as still frames. Watch once for comprehension, once for emotion, and once for visible mechanics."]],["Place cuts according to attention and performance change.","Compare adjacent cut frames and articulate their emotional effect."],["Cut to the listener just before their attempt to hide a reaction.","A moving hand lands in the same attention zone after the cut."],["Cutting every dialogue turn to the current speaker.","Using match rules without asking what the audience needs next."],[BMD_EDIT,ADOBE_CONT]),
  "Continuity, Discontinuity & Match Logic": lesson("Continuity preserves the spatial, temporal and causal relationships the audience needs; discontinuity breaks selected relationships to compress, disturb or call attention to construction.",[["What must match","Track screen direction, eyeline, action phase, prop state, light, sound perspective and story time. Not every detail has equal narrative weight."],["Match on action","Cut during movement when attention follows its trajectory. Match energy and phase, not merely the presence of the same gesture."],["Mental map","Establish geography before demanding that viewers infer unseen relations. A neutral view or motivated camera move can reset orientation after an axis crossing."],["Useful discontinuity","Jump cuts can remove time or destabilize identity; mismatches can express fractured memory. The broken cue must read as intention rather than accidental sloppiness."],["Diagnose the bump","Name the contradictory cue and repair only if it obstructs the scene. A dissolve often hides neither wrong direction nor missing causality."]],["Audit a cut for specific continuity cues.","Use one deliberate discontinuity with a stated narrative function."],["A hand reaches in the wide and completes the same phase in close-up.","A jump series removes waiting while preserving cause and destination."],["Treating continuity as identical pixels.","Covering an unresolved spatial contradiction with a transition effect."],[ADOBE_CONT,BMD_EDIT]),
  "Screen Direction, Eyelines & Action": lesson("Screen direction and eyelines create an inferred off-screen geometry; action matching sustains that geometry while bodies and objects move through cuts.",[["Axis of action","Camera positions on one side of the active line normally preserve left-right relations. The line changes when blocking creates a new dominant relation."],["Crossing legibly","Show the crossing in a moving shot, use a neutral angle, or re-establish geography. An unexplained reversal can make pursuit or dialogue partners appear misaligned."],["Eyeline geometry","The off-screen mark, camera height and distance from axis determine gaze angle. Two singles match when their implied looks are reciprocal, not merely opposite."],["Action phase","Overlap action across takes and cut at a comparable phase and speed. Small continuity errors become less visible when intention and momentum remain continuous."],["Expressive violations","A reversed direction or impossible eyeline can signal disorientation, but surrounding shots must teach the audience that the break is purposeful."]],["Draw an axis plan and preserve or intentionally reset direction.","Match reciprocal eyelines and action energy across singles."],["A dolly crosses the line on screen, allowing subsequent angles from the new side.","The runner continues left-to-right through different locations to preserve pursuit momentum."],["Applying the 180-degree rule to a line that moved with the actors.","Matching gaze direction while camera heights imply different partners."],[ADOBE_CONT,BMD_EDIT]),
  "Pacing, Rhythm & Breath": lesson("Pacing is the rate of dramatic change; rhythm is the pattern of durations and accents through which that change is felt. Shot length alone measures neither.",[["Information rate","A long shot can feel urgent when viewers search actively; rapid cuts can feel slow when each repeats the same fact. Track new information and changed pressure."],["Performance rhythm","Breath, hesitation, interruption and reaction create internal timing. Cutting pauses automatically can remove thought and flatten relationships."],["Visual rhythm","Movement direction, scale changes and compositional density create accents across cuts. Alternate compression and release instead of enforcing one tempo."],["Sonic rhythm","Dialogue cadence, effects and silence can motivate or counterpoint picture cuts. Music should not dictate every edit unless the sequence's concept requires it."],["Revision pass","Screen without stopping and mark where attention drifts or comprehension races. Change the earliest causal beat, then replay the whole phrase."]],["Distinguish pace from average shot length.","Shape a scene through purposeful compression, holds and release."],["A long hold accelerates tension because the expected arrival is delayed.","A rapid montage slows emotionally when repeated failures accumulate weight."],["Shortening every shot to make a scene exciting.","Removing all silence between dialogue lines."],[BMD_EDIT,ADOBE_CONT]),
  "J-Cuts, L-Cuts & Audio Bridges": lesson("Split edits let listening and looking change at different times: a J-cut introduces incoming audio before picture, while an L-cut carries outgoing audio beyond the picture cut.",[["J-cut anticipation","Incoming sound prepares a person, location or event before it appears. The audience begins imagining the next space and crosses the visual cut with a question already active."],["L-cut consequence","Outgoing speech or ambience continues over a reaction, result or new location. It frees the image from the speaker and can connect words to a larger meaning."],["Acoustic continuity","Room tone and perspective must bridge the overlap. A technically correct split edit still bumps if backgrounds or reverberation switch abruptly."],["Meaningful trim","Choose the overlap by phrase, consonant, breath and dramatic relation—not a fixed number of frames. Avoid clipping word attacks or letting old ambience mask essential new sound."],["Beyond dialogue","Effects, music and environmental sound can bridge scenes by similarity, contrast or cause. A bridge may disguise geography or intentionally create an associative cut."]],["Construct and identify J-, L- and sound-bridge edits.","Trim overlaps for meaning and acoustic plausibility."],["We hear a train before cutting from the office to the platform.","A confession continues over the listener's silent decision."],["Applying equal overlap duration to every dialogue exchange.","Ignoring abrupt room-tone changes beneath a smooth voice edit."],[ADOBE_SPLIT,BMD_EDIT]),
  "Montage, Ellipsis & Compression": lesson("Ellipsis removes inferable time; montage selects and juxtaposes fragments so the audience constructs progression, comparison or an idea larger than any single shot.",[["Inference bridge","Retain enough cause, consequence or recurring motif for viewers to bridge omitted steps. A gap becomes confusion when the new state lacks an intelligible relation to the old."],["Progressive selection","Every shot should add state: effort, cost, scale, skill, place or emotional change. Repeating attractive versions of one fact creates length without progression."],["Associative montage","Juxtaposition can compare spaces, create metaphor or imply causality. Test whether the relation survives without explanatory music or titles."],["Time signatures","Wardrobe, light, repeated framing, sound and evolving props can mark elapsed time. Choose a consistent device rather than using every possible cue."],["Compression and breath","A compressed sequence still needs accents and releases. Vary shot duration and sound density so important changes have perceptual weight."]],["Design a montage in which each shot contributes a new state.","Remove time while preserving causal and emotional legibility."],["Repeated doorway compositions show a workplace changing across seasons.","Cutting from a match strike to sunrise skips a night while preserving causal feeling."],["Using montage as a container for miscellaneous B-roll.","Letting song beats replace story progression."],[BMD_EDIT,ADOBE_SPLIT]),
  "Structure, Feedback & Revision": lesson("Editorial revision improves structure by comparing what viewers actually know, expect and feel with the intended beat progression, then changing the earliest cause of a problem.",[["Map the cut","For every beat, state incoming knowledge, action, turn and outgoing condition. The map exposes repetition, missing cause and scenes that do not change the larger sequence."],["Preserve versions","Duplicate timelines and label passes before structural changes. Comparison protects successful accidents and distinguishes improvement from mere novelty."],["Screen cold","Do not explain intention beforehand. Ask where viewers became confused, ahead, detached or newly engaged and collect exact time-coded observations."],["Interpret notes","Repeated observations are evidence; proposed fixes are hypotheses. Locate the underlying information or rhythm problem rather than executing every suggestion literally."],["Separate passes","Revise structure, performance, rhythm, sound and polish in distinct passes. Fine transitions are wasted when a scene may still be removed."]],["Run a neutral screening and convert observations into hypotheses.","Revise from structural causes while preserving comparable versions."],["Three viewers disengage before the same reveal, leading to an earlier information audit.","A scene map reveals two consecutive beats that achieve the same value change."],["Defending intention while viewers are still describing their experience.","Polishing color and sound before resolving scene order."],[BMD_EDIT,ADOBE_CONT]),
  "Narrative Edit Chapter Boss": lesson("The narrative-edit capstone proves that individual cuts, scenes and the full sequence work together to direct attention, preserve chosen continuity and transform dramatic conditions.",[["Performance assembly","Begin with truthful actions, reactions and complete beats. Resist premature speed; establish what each scene actually contains."],["Information pass","Track what the audience knows and when. Remove redundancy, restore missing causes and decide which surprises require concealment."],["Spatial and sonic pass","Make geography intelligible where needed, then build room tone, perspective and split edits so picture changes inhabit one world."],["Rhythm pass","Shape tension through duration, interruption, holds and release. Compare the sequence without music to expose weak visual or dramatic progression."],["Evidence and finish","Screen cold, log notes, revise a duplicated timeline and complete technical QC. Defend retained discontinuities by their effect, not habit."]],["Complete and evaluate a coherent narrative scene or sequence.","Diagnose problems separately at cut, beat, scene and sequence scale."],["A reaction replaces redundant dialogue and becomes the scene's turn.","A deliberate jump cut remains because viewers read lost time rather than an error."],["Using smoothness as the only quality criterion.","Attempting to fix missing story information with faster cutting."],[BMD_EDIT,ADOBE_CONT]),

  "Color Perception & Context": lesson("Color is a perceptual comparison, not a fixed sensation: adaptation, neighboring colors, luminance, viewing environment and memory all change how the same signal appears.",[["Adaptation","Vision partially normalizes the prevailing illuminant, so a display judged after looking at warm room light appears different. Neutral surround and adaptation time make judgments repeatable."],["Simultaneous contrast","A color shifts perceptually against its neighbors; skin can appear greener beside magenta or brighter against darkness without its measured value changing."],["Luminance interaction","Brightness changes perceived saturation and hue discrimination. Evaluate a look in motion and at delivery brightness, not only with an isolated picker."],["Memory colors","Viewers are sensitive to plausible skin, foliage and sky but memory is not measurement. Use scopes and references while preserving intentional context."],["Creative control","Build palette relationships across costume, design, light and grade. Grading cannot cleanly separate colors that production rendered identical."]],["Explain how adaptation and surround alter color judgment.","Design a palette using relationships rather than isolated swatches."],["A muted face appears vivid when the environment is nearly monochrome.","The same gray patch looks warm against blue and cool against orange."],["Grading in colored ambient light.","Assuming numerical equality guarantees perceptual matching."],[BMD_COLOR,ACES]),
  "Gamut, Gamma & Transfer Functions": lesson("Gamut describes reproducible chromaticities; a transfer function maps scene light or display light to signal values. Confusing them causes wrong transforms and unpredictable contrast or saturation.",[["Two dimensions","Color space primaries define gamut while transfer characteristics define tone encoding. Rec.709 primaries and a log curve are separate properties."],["Scene and display referred","Scene-referred values represent captured light relationships; display-referred values target emitted output. Grading tools behave differently depending on where transforms occur."],["Log encoding","Log allocates code values efficiently across camera dynamic range but is not meant to look finished. It needs the correct input interpretation and output transform."],["Transform chain","Declare source, working and output spaces once. A missing transform looks flat; a duplicated transform creates excessive contrast and clipping."],["Out-of-gamut behavior","Saturation can push colors beyond delivery gamut. Gamut mapping should compress boundaries gracefully rather than hard clip channel detail."]],["Distinguish gamut from transfer function.","Diagram a source-to-working-to-display transform chain."],["A camera-log clip is tagged correctly before creative grading.","Wide-gamut work is mapped to Rec.709 only at output."],["Using a LUT without knowing its expected input.","Applying both automatic management and a duplicate CST."],[ACES,BMD_COLOR]),
  "Scopes and Signal Evaluation": lesson("Scopes are objective views of encoded image data: waveform locates level by horizontal position, parade separates channels, vectorscope shows chroma direction and strength, and histogram summarizes distributions.",[["Waveform","Use it to find clipping, compare faces and inspect gradients because horizontal image position is retained. Scale depends on video/data levels and signal stage."],["RGB parade","Aligned neutral areas should show related channel levels; separations reveal color casts or intentional colored light. Parade also exposes channel-specific clipping."],["Vectorscope","Angle corresponds broadly to hue and radius to chroma. Skin indicators are guides, not mandatory lines for every ethnicity, light or creative intent."],["Histogram limits","A histogram hides location, so small clipped regions can disappear in a broad distribution. It is useful for overview, not complete exposure diagnosis."],["Scope context","Know whether scopes view log, timeline-managed or output-transformed data. A correct target in the wrong signal stage is still wrong."]],["Choose the appropriate scope for tonal, channel and chroma questions.","Evaluate clipping and neutrality without replacing visual judgment."],["Parade reveals blue-channel clipping hidden in luma.","Waveform identifies which side of frame contains an over-level window."],["Treating the skin-tone line as a universal beauty target.","Reading legal-range targets on an untransformed log signal."],[BMD_COLOR,ACES]),
  "Balance, Neutrality & Shot Matching": lesson("Balancing establishes believable exposure and chromatic relationships; matching makes adjacent shots feel continuous while respecting motivated changes in angle and light.",[["Choose references","Use a known neutral only when it was actually neutral under the intended light. Memory colors and production references help when no chart exists."],["Order of work","Set color management, then exposure and contrast, then white balance and shot match. Matching before input interpretation produces fragile corrections."],["Match relationships","Compare skin, key backgrounds, black floor and highlight character, not average RGB values. Different compositions legitimately yield different overall scope shapes."],["Anchor shot","Select a representative hero angle and match neighboring shots to its perceptual intent. Use split-screen and rapid playback to reveal drift."],["Motivated variation","A reverse may be cooler because it faces a window. Preserve physically or narratively motivated differences instead of neutralizing the entire scene."]],["Balance a shot in a defined color pipeline.","Match a scene by key perceptual anchors while preserving motivated variation."],["A neutral wardrobe patch helps remove an accidental green cast.","Reverse angles match skin and black level while retaining different window influence."],["Using auto-balance on a deliberately warm object.","Forcing every shot to identical waveform distributions."],[BMD_COLOR,ACES]),
  "Contrast, Saturation & Density": lesson("Contrast organizes tonal separation, saturation controls chromatic distance from neutral, and perceived density emerges from their interaction with exposure, color and display rendering.",[["Contrast pivot","Contrast changes separation around a pivot; it can crush quiet shadow relationships or blow highlight texture even when endpoints remain nominally legal."],["Saturation is not independent","Increasing chroma can change perceived brightness and drive channels out of gamut. Scene-referred and display-referred saturation tools produce different trajectories."],["Density","Rich color often comes from controlled luminance and hue-selective shaping, not global saturation. Darkening a color can make it feel denser while preserving skin restraint."],["Local hierarchy","Use tonal zones to direct attention. A globally punchy image with equal local contrast everywhere competes with itself."],["Sequence behavior","Check fades, cuts and varied displays. A look that works on one hero frame may make darker coverage brittle or noisy."]],["Shape contrast without losing intended highlight and shadow information.","Create color density without indiscriminate global saturation."],["Background chroma is restrained so a modestly saturated costume leads attention.","A gentle toe gives blacks weight while retaining texture."],["Crushing blacks to imitate cinematic contrast.","Increasing global saturation until one channel clips."],[BMD_COLOR,ACES]),
  "Secondaries, Skin & Selective Control": lesson("Secondary correction isolates regions by hue, luminance, saturation, geometry or tracking so a specific problem can be changed without destabilizing the rest of the image.",[["Qualifier limits","Real objects contain wide, noisy value ranges. Build a clean key with softness and denoise, then inspect the matte rather than trusting the normal image."],["Windows and tracking","A power window supplies spatial intent; tracking follows motion. Include natural edge transitions and verify occlusion, blur and frame exits."],["Skin variation","Skin contains warm and cool zones, speculars and reflected environment. Preserve internal variation instead of forcing every pixel to one hue line."],["Order and causality","Fix global balance before isolating a symptom. A broad cast corrected upstream may eliminate several unnecessary secondaries."],["Invisible intervention","Bypass frequently and review motion at full resolution. A technically clean still key can chatter, halo or detach in playback."]],["Build and inspect a stable qualified correction.","Refine skin while preserving texture and lighting variation."],["A tracked window gently controls a face moving past a practical.","A costume key reduces only an out-of-gamut red."],["Keying skin before correcting global white balance.","Judging matte edges on one stationary frame."],[BMD_COLOR,ACES]),
  "Look Design, Display & QC": lesson("Look design creates repeatable expressive relationships inside a managed pipeline; display preparation and quality control ensure those relationships survive the intended output.",[["Look architecture","Separate technical input/output transforms from creative contrast, palette and texture. This keeps the look portable and prevents accidental double transforms."],["Reference conditions","Use a profiled display, neutral surround and intended luminance where possible. Consumer vivid modes are not a stable grading reference."],["Stress testing","Apply the look across skin tones, exposure extremes, mixed light and saturated objects. A hero-shot look that breaks normal coverage is not production-ready."],["Delivery mapping","Select correct color tags, legal levels and codec. Review the rendered file through the actual playback path rather than trusting the grading timeline alone."],["QC passes","Inspect for clipping, gamut excursions, banding, noise, key chatter, dead pixels, flash frames and shot mismatch. Conduct both technical and uninterrupted creative screenings."]],["Build a look separated from technical color transforms.","Perform display-aware render QC on a complete sequence."],["One look node structure is stress-tested across every scene condition.","The uploaded file is re-downloaded and checked for tag and gamma behavior."],["Designing a look on one ideal close-up.","Approving from the timeline without watching the encoded master."],[BMD_COLOR,ACES]),
  "Finished Scene Chapter Boss": lesson("The color-finishing capstone manages source color, balances and matches a full scene, develops an expressive look, applies stable selective corrections and validates the rendered delivery.",[["Pipeline first","Inventory camera spaces and choose working/output transforms before grading. Confirm data levels and monitoring."],["Balance pass","Normalize exposure and chromatic bias shot by shot while protecting intentional lighting relationships."],["Continuity pass","Use a hero reference, groups and split-screen to align skin, key neutrals, contrast and density across cuts."],["Look and secondaries","Build the sequence look globally, then use tracked or qualified corrections only for remaining local needs."],["Deliver and audit","Render the target codec, inspect tags and scopes, then watch the actual file uninterrupted and in a technical pass."]],["Finish a color-managed scene from source interpretation through master QC.","Document creative intent and all delivery assumptions."],["The warm practical remains warm while accidental green camera drift is removed.","A render check catches mismatched full/video levels before delivery."],["Beginning with isolated beauty keys before scene balance.","Calling the grade finished without checking the exported file."],[BMD_COLOR,ACES]),

  "Describe Before You Interpret": lesson("Film analysis becomes testable when it begins with observable choices—what appears and sounds, when it changes and in relation to what—before claiming meaning or intention.",[["Observation","Record shot scale, position, movement, light, color, performance, sound and duration in neutral language."],["Pattern","One low angle proves little; recurrence, contrast and change give a choice analytical weight."],["Effect","Describe what information becomes available, withheld or emphasized for a viewer before naming a theme."],["Interpretation","Connect formal evidence to a plausible meaning while admitting alternatives. Avoid claims about author intention without sources."],["Craft transfer","Convert the finding into a controllable filmmaking proposition that can be tested in a new scene."]],["Separate description, pattern, effect and interpretation.","Support a reading with time-coded audiovisual evidence."],["At 02:14 the first close-up interrupts six shared frames, isolating the witness.","The score disappears at each lie, a pattern that changes how silence functions."],["Calling a frame ominous without describing why.","Inferring production intention from one isolated choice."],[YALE,BFI]),
  "Shot Scale, Duration & Pattern": lesson("Shot scale controls access to body, environment and detail; duration controls reading time; their sequence creates expectation and emphasis.",[["Scale is relational","A close-up is defined by framing and viewing context, not lens alone. State what is included and excluded."],["Duration","Measure from cut to cut, but interpret duration by on-screen change and information density."],["Pattern baseline","Repeated wides establish a norm; a close-up gains force partly because it departs from that norm."],["Transitions","Track whether scales narrow, widen, alternate or abruptly reset across a beat."],["Meaning through consequence","Ask what the scale pattern lets viewers know or feel at each moment, not whether close universally means intimate."]],["Log shot scale and duration accurately.","Explain how a scale-duration pattern changes attention."],["A sequence narrows from group wide to isolated close-up as consensus collapses.","One long static shot feels rapid because entrances continually revise the frame."],["Treating shot-size labels as interpretations.","Equating shorter average duration with greater dramatic pace."],[YALE,BFI]),
  "Mise-en-scÃ¨ne and Production Design": lesson("Mise-en-scène is the organized material event before the camera—setting, costume, makeup, props, lighting, staging and performance—whose relations build the film's visible world.",[["Inventory","Identify concrete objects, surfaces, colors, wear, spatial boundaries and performer placement."],["Function","Distinguish practical story information from expressive pattern: a prop may enable action, signify history or both."],["Hierarchy","Composition and light determine which designed elements become legible and when."],["Change over time","Track spaces and costumes across the narrative; alteration often carries more meaning than a single symbolic object."],["Production causality","Analysis should not pretend design alone created the frame: lens, exposure, grade and blocking mediate what design contributes."]],["Analyze designed elements as interacting systems.","Trace one production-design motif through narrative change."],["A pristine room accumulates damage after each failed negotiation.","Costume hue links two characters before dialogue reveals kinship."],["Listing props without relating them to staging or story.","Assigning fixed symbolic meanings regardless of context."],[YALE,BFI]),
  "Camera, Lens & Spatial Evidence": lesson("Camera position, focal length, focus, height and movement regulate spatial relationships and viewer access; analysis must distinguish perspective from magnification and framing.",[["Position","Perspective follows camera location: foreground-background size relations change when the camera moves."],["Lens and field","Focal length with sensor size determines field of view from that position; framing alone cannot prove a lens choice."],["Depth cues","Occlusion, scale, parallax, focus and atmospheric separation construct perceived depth."],["Movement","Describe origin, destination, speed and subject relation, then ask what new knowledge the move provides."],["Epistemic caution","Infer only what visible evidence supports. Avoid declaring exact focal lengths or rigs from an image without metadata."]],["Describe spatial evidence without confusing lens and perspective.","Explain how camera access structures viewer knowledge."],["Parallax during a lateral move reveals the hidden observer.","A fixed distant frame denies privileged access during a confession."],["Claiming telephoto compression without considering camera distance.","Calling every unstable image handheld."],[YALE,BFI]),
  "Lighting, Color & Tonal Evidence": lesson("Lighting and color analysis examines direction, quality, contrast, exposure, palette and change, while separating photographed evidence from assumptions about fixtures or grading tools.",[["Direction and quality","Read shadow placement, edge hardness, catchlights and falloff to infer source relationships."],["Tonal hierarchy","Identify where darkest and brightest values guide attention and how much detail remains."],["Color relationships","Describe warm-cool, complementary, analogous and neutral relations in context rather than naming isolated hues."],["Continuity and change","Track when lighting or palette shifts and whether the change follows place, time, psychology or narrative structure."],["Limits of inference","The final image combines design, source spectrum, camera response and grade; avoid asserting an exact on-set cause without documentation."]],["Support lighting claims with visible cues.","Trace tonal or palette change through a sequence."],["A face loses fill as trust collapses, deepening the eye socket on the decisive line.","Warm practicals remain constant while the exterior transitions toward blue."],["Calling any dark frame low-key without analyzing contrast.","Assuming a color was created exclusively in grading."],[YALE,BFI]),
  "Sound, Edit & Temporal Evidence": lesson("Sound and editing organize time beyond the photographed frame through duration, order, overlap, rhythm, off-screen space and audiovisual relation.",[["Track layers","Separate dialogue, effects, ambience and music; note entrances, exits, perspective and relative foreground."],["Cut function","Record what changes across each cut: viewpoint, time, space, information or association."],["Overlap","J/L cuts and sound bridges can lead, delay or contradict picture, creating continuity or anticipation."],["Rhythm","Relate shot duration to performance, movement and sound accents rather than counting cuts alone."],["Off-screen world","Sound can establish causes and spaces never shown, widening or restricting what viewers know."]],["Create a time-coded audiovisual event log.","Explain how sound and cut relations shape temporal experience."],["An unseen elevator bell triggers the cut before its doors appear.","Music continues across years while effects mark each ellipsis."],["Analyzing images while treating sound as decoration.","Calling a cut seamless without naming which continuity cue carries it."],[YALE,BMD_EDIT]),
  "Comparative Analysis & Creative Transfer": lesson("Comparison isolates a formal variable across works or moments; creative transfer converts the discovered relationship into a new test instead of copying surface style.",[["Comparable question","Choose works that answer the same craft problem—revealing a threat, staging power—not merely the same genre."],["Common vocabulary","Log equivalent variables and sequence boundaries so evidence is comparable."],["Difference and consequence","Explain how changed position, timing or sound alters audience access under each context."],["Avoid imitation","Extract a principle such as delayed information, then redesign it for different characters and constraints."],["Controlled test","Create two versions changing the target variable and collect viewer observations without explaining the hypothesis."]],["Compare sequences using shared formal criteria.","Turn analysis into an original controlled craft experiment."],["Two doorway reveals are compared by prior knowledge and sound cue timing.","A discovered use of empty foreground becomes a new blocking test, not a copied frame."],["Comparing entire films with no bounded question.","Copying palette or composition without its dramatic function."],[YALE,BFI]),
  "Sequence Analysis Chapter Boss": lesson("The analysis capstone builds an evidence-led account of how image, sound, performance and editing cooperate across a bounded sequence, then tests one finding through practice.",[["Bound the object","Select a coherent sequence and record start, end and dramatic state change."],["Event log","Time-code shots, sound events, blocking changes and formal transitions without interpretation first."],["Find the system","Identify repetitions, contrasts and turns across multiple channels rather than chasing isolated symbols."],["Argue from effects","Build a claim about viewer knowledge or feeling and support it with precise moments plus plausible alternatives."],["Transfer","Design and evaluate a short filmmaking exercise that applies the principle under new conditions."]],["Produce a rigorous multimodal sequence analysis.","Demonstrate creative transfer through a controlled artifact."],["The claim about isolation uses framing, eyeline, room tone and cut pattern together.","A recreated information delay tests whether the principle survives another genre."],["Summarizing plot instead of analyzing form.","Presenting screenshots without temporal and sonic context."],[YALE,BFI]),

  "From Intent to Executable Plan": lesson("An executable plan translates creative intention into required results, dependencies, ownership, timing, resources and verified contingencies.",[["Define the result","State what must be seen, heard and changed in the scene before choosing gear."],["Dependencies","Map performer, location, light, sound, art, power, access and post requirements in causal order."],["Ownership","Assign every preparation and safety-critical action to a named role with a confirmation point."],["Tests","Spend prep on uncertainties that could stop production: power, noise, lens fit, data rate or stunt method."],["Fallbacks","A useful contingency preserves the dramatic requirement with less time or complexity; it is not simply lower quality."]],["Convert scene intent into owned production requirements.","Identify and test the highest-impact uncertainty."],["A sunset beat gets a timed priority order and an interior fallback preserving silhouette.","The location scout records actual dialogue noise at the planned hour."],["Starting with an equipment wish list.","Writing contingencies no department has rehearsed."],[CSATF,DGA]),
  "Script Breakdown for Craft Needs": lesson("A craft breakdown marks every element a scene requires, then connects those elements to departments, continuity, schedule, safety and post-production.",[["Read in passes","First understand drama; then mark cast, background, props, wardrobe, makeup, vehicles, animals, effects, sound and special equipment."],["Separate explicit and implied","Rain may be written; wet wardrobe, floor protection, continuity and sound effects may be implied."],["Track continuity","Record which items change state, are consumed, damaged or require duplicates across nonsequential shooting."],["Flag risk","Elevated work, atmosphere, weapons, water, vehicles and fatigue require qualified review, not casual checklist treatment."],["Feed the plan","A breakdown matters only when items become schedule, budget, test and responsibility decisions."]],["Break down a scene for explicit and implied craft needs.","Trace a changing prop or costume through continuity and reset requirements."],["A smashed phone triggers duplicates, screen graphics, sound and safe breakaway planning.","Night exterior implies power, warmth, visibility and transport controls."],["Highlighting nouns without identifying operational consequences.","Assuming the breakdown itself confirms availability."],[CSATF,DGA]),
  "Shot Lists, Floor Plans & Storyboards": lesson("Shot lists describe required coverage, floor plans prove spatial feasibility and screen direction, and storyboards previsualize selected compositions and action moments.",[["Different documents","Do not force one artifact to carry all information: lists track completion, plans track geometry, boards communicate images."],["Shot-list purpose","Include subject, size, action/beat, movement, sound needs and priority—not only arbitrary shot numbers."],["Floor-plan logic","Place walls, doors, windows, actors, camera positions, axes and movement to reveal access and lighting conflicts."],["Storyboard selectively","Board complex reveals, effects, choreography and transitions where timing or composition needs shared understanding."],["Update after rehearsal","Documents serve the scene; revise them when truthful blocking changes while retaining must-have editorial beats."]],["Create mutually consistent shot-list, floor-plan and board materials.","Prioritize coverage by dramatic and editorial necessity."],["The floor plan reveals that a planned reverse crosses the active axis and blocks an exit.","A storyboard communicates the exact frame where a practical effect occurs."],["Treating a storyboard as a mandatory frame-by-frame prison.","Listing shots without the beat each protects."],[BFI,DGA]),
  "Set Roles, Communication & Etiquette": lesson("A film set works through defined responsibilities and communication paths that protect concentration, safety and accountability while many departments act at once.",[["Role clarity","Know who owns creative approval, set operation, camera, grip, electric, sound, art, continuity and data in the production's actual scale."],["Chain of communication","Route requests through department leads and assistant direction so changes reach everyone affected."],["Calls and confirmation","Use concise standard calls, repeat safety-critical information and receive explicit confirmation rather than assuming silence means readiness."],["Set discipline","Protect takes, eyelines, recordings and restricted areas; ask before touching another department's equipment or moving continuity items."],["Respect and access","Names, boundaries, breaks and reporting channels are production infrastructure, not optional courtesy."]],["Communicate a change through affected roles.","Demonstrate professional set behavior around takes and equipment."],["A lens change reaches camera, focus, lighting, sound and AD before the next setup.","A hazard call stops movement and receives confirmation before reset."],["Giving conflicting instructions directly to individual crew.","Prioritizing hierarchy over reporting a safety concern."],[DGA,CSATF]),
  "Safety, Risk & Data Responsibility": lesson("Production safety identifies hazards, reduces likelihood and consequence, empowers stopping work, and treats irreplaceable media as a duty of care.",[["Hazard and risk","A hazard can cause harm; risk combines likelihood and severity under current conditions."],["Hierarchy of controls","Eliminate or substitute hazards before relying on procedures and personal protective equipment."],["Qualified authority","Stunts, weapons, vehicles, water, electricity, heights, atmosphere and animals require trained responsible personnel and applicable guidance."],["Dynamic review","Weather, fatigue, crowding and changed blocking can invalidate the morning plan. Reassess when conditions change."],["Data safety","Use verified copies on independent media, preserve originals until confirmation, document custody and protect sensitive footage."]],["Conduct a scene-specific risk review and name controls.","Design and verify a redundant media handoff."],["A wet floor is eliminated or isolated before adding warning and footwear controls.","Checksummed copies exist on two devices before a card is cleared."],["Treating a signed form as proof that conditions remain safe.","Counting two folders on one drive as two backups."],[CSATF,DGA]),
  "Coverage Strategy & Time Tradeoffs": lesson("Coverage strategy spends finite time on the shots and sound that carry story, performance and editability, with explicit priorities for what may be simplified.",[["Must-have beats","Identify the scene's turn, necessary geography and indispensable performance reactions."],["Dependency order","Capture shots constrained by daylight, effects, location or performer first when that does not damage scene work."],["Coverage value","A new angle should add information, emotion or a transition—not duplicate material without purpose."],["Time estimates","Include lighting, rehearsal, reset, focus, sound and data time, not only record duration."],["Graceful reduction","Drop decorative coverage before the connective shot that makes the scene intelligible; communicate the editorial consequence."]],["Prioritize a shot plan under a fixed schedule.","Make a time tradeoff while preserving dramatic continuity."],["The company protects the reveal and reaction before an optional slider insert.","A complex master replaces several redundant singles after rehearsal proves it works."],["Calling every shot essential.","Saving time on slate, sound or data verification."],[DGA,BFI]),
  "Media, Slating & Handoffs": lesson("Media workflow preserves identity and integrity from slate through camera file, sound file, report, verified copies and editorial relink.",[["Slate identity","Scene, setup and take connect picture, sound and reports; speak and show accurate information and mark false starts clearly."],["Metadata consistency","Camera, sound and script supervision should share naming, frame rate, timecode and preferred-take conventions."],["Offload","Copy with verification, inspect file counts and representative playback, then create independent copies before reuse."],["Reports","Deliver camera, sound, script and data notes that flag technical faults, wild tracks, preferred takes and continuity exceptions."],["Chain of custody","Record cards received, destinations, verification and release. Never erase based on assumption or an unlabeled folder."]],["Run a traceable slate-to-editor media workflow.","Verify and document independent media copies."],["Editorial can find the wild line because slate, filename and sound report agree.","A card is released only after checksums and playback on two destinations."],["Renaming source files ad hoc after ingest.","Confusing copy completion with verified integrity."],[CSATF,BFI]),
  "Production Readiness Chapter Boss": lesson("The production-readiness capstone proves that a short scene can be made safely and edited successfully through integrated breakdown, logistics, communication, coverage and data controls.",[["Creative requirements","State the scene's dramatic result and the image, sound and performance evidence required to deliver it."],["Integrated breakdown","Connect cast, location, design, technical, continuity and post needs to named owners and deadlines."],["Safety and contingency","Complete a live risk review, obtain qualified support and rehearse a fallback for the highest-impact dependency."],["Executable day","Build a realistic shot order with setup, rehearsal, resets, breaks, priorities and communication checkpoints."],["Proof of closure","Run slate and media handoff, verify backups and assemble the scene. Use editorial gaps to revise the next production plan."]],["Prepare and execute a safe, traceable short production.","Demonstrate readiness with artifacts, tests and an editable result."],["The plan connects a breakaway prop to duplicates, safety, coverage, sound and reset time.","The completed edit validates that priority coverage and media labels worked."],["Calling a production ready because a call sheet exists.","Evaluating success before media verification and edit assembly."],[CSATF,DGA]),
};
